-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "ruRU" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.hunter.ranged.Name"] = "Дальний бой"
L["rm.era.hunter.ranged.Description"] = "Любой охотник с 1 по 60 уровень, все ветки талантов. Начало боя: Метка охотника, Прицельный выстрел и Автоматическая стрельба. В одиночной игре танкует питомец: ваш собственный Укус змеи, затем Прицельный выстрел, Чародейский выстрел и Залп — только пока маны больше половины, Шокирующий выстрел, чтобы держать врага на расстоянии, пока у вас нет питомца. В группе Прицельный выстрел и Залп сразу после автоматического выстрела, чтобы он никогда не задерживался, Укус змеи вне рейдов, Чародейский выстрел — только перед Прицельным выстрелом или по умирающей цели. Удары ближнего боя, когда враг слишком близко, мгновенные выстрелы в движении, Залп и Град стрел против трёх и более врагов. Напоминания: Дух ястреба (до него — Дух обезьяны), Аура меткого выстрела, уход за питомцем, Быстрая стрельба, Звериный гнев и расовые способности против элитных противников и в подземельях, Устрашение и Притвориться мертвым. Ловушки, Подрезать крылья, Кормление питомца, Усмиряющий выстрел и позиционирование остаются за вами."
L["rm.era.hunter.ranged.icyveins.Name"] = "Дальний бой, без ожидания автовыстрела (Icy Veins)"
L["rm.era.hunter.ranged.icyveins.Description"] = "По умолчанию выключена; включите её для оружия дальнего боя быстрее 3,0 секунды. Как «Охотник: дальний бой», но в группе Прицельный выстрел и Залп применяются сразу по готовности, даже если это задерживает автоматический выстрел, Укус змеи не используется никогда, а Быстрая стрельба, Звериный гнев и расовые способности используются в каждом бою."
L["rm.era.hunter.ranged.simulator.Name"] = "Дальний бой, Укус змеи в рейде (симулятор)"
L["rm.era.hunter.ranged.simulator.Description"] = "По умолчанию выключена; включите её, если в рейде есть место для вашего укуса среди отрицательных эффектов. Как «Охотник: дальний бой», но в группе Укус змеи поддерживается везде, в том числе в рейдах, обновляется, когда осталось меньше 5 секунд, а Прицельный выстрел и Залп оба восстанавливаются, и Чародейский выстрел не используется никогда."
L["rm.forever.hunter.ranged.Name"] = "Дальний бой (Wowhead)"
L["rm.forever.hunter.ranged.Description"] = "Любой охотник дальнего боя с 1 по 60 уровень («Повелитель зверей», «Стрельба», а также «Выживание» до Удара долгонога); также ротация охотника по умолчанию в Forever. Начало боя: Метка охотника, Снайперский выстрел, пока действуют Быстрые убийства, Автоматическая стрельба. Затем ваш собственный Укус змеи, Призыв ястреба дважды и Чародейский выстрел один раз за их общее время восстановления (до Призыва ястреба — Чародейский выстрел по готовности), Снайперский выстрел под Быстрыми убийствами или по элитным противникам, Прицельный выстрел. Если с вами сражаются два и более врага: Залп вместо Прицельного выстрела, Взрывная ловушка при трёх врагах рядом с вами, Град стрел при пяти. В движении — только мгновенные выстрелы. Противник в зоне ближнего боя получает Удар ящера и Укус мангуста. Напоминания: Дух ястреба (до него — Дух обезьяны), Аура меткого выстрела, призыв и воскрешение питомца, Быстрая стрельба, Звериный гнев и Кровавое неистовство против элитных противников или в подземельях, Устрашение, когда противник бьёт вас. Команды питомцу, кормление, кайт и Притвориться мертвым остаются за вами; если вы играете с Одиноким волком, выключите напоминания о питомце. Ротация никогда не читает вашу ману и здоровье кого бы то ни было, которые Forever скрывает от аддонов, поэтому Метка охотника и Укус змеи накладываются на каждую цель, а Лечение питомца — за вами."
L["rm.forever.hunter.ranged.mobalytics.Name"] = "Дальний бой, экономия маны (Mobalytics)"
L["rm.forever.hunter.ranged.mobalytics.Description"] = "Экономный по мане стиль прокачки Mobalytics — альтернатива рекомендуемой встроенной ротации «Дальний бой» от Wowhead, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Поддерживает ваш Укус змеи, одного призванного ястреба, Прицельный выстрел (Залп против двух и более врагов) и после изучения Призыва ястреба никогда не использует Чародейский выстрел; второй ястреб на цели с большим запасом здоровья опущен, так как Forever скрывает здоровье цели. Те же начало боя, ближний бой, движение и напоминания, что и во встроенной ротации Wowhead."
L["rm.forever.hunter.survival.Name"] = "Выживание, ближний бой (Wowhead)"
L["rm.forever.hunter.survival.Description"] = "«Выживание» в ближнем бою с оружием в обеих руках, когда «Выживание» — ваша основная ветка талантов с 21 очком (уровень Удара долгонога); до этого, как советуют руководства, прокачка идёт со встроенной ротацией дальнего боя. Начинает бой Меткой охотника и Укусом змеи, затем Укус мангуста, Удар долгонога, Удар ящера и Контратака, а при трёх и более врагах — Взрывная ловушка. Вне ближнего боя стреляет: Укус змеи, Чародейский выстрел, Прицельный выстрел, Автоматическая стрельба. Напоминания: Дух зверя, Метка охотника (она нужна для Обнаружения добычи), Быстрая стрельба и Кровавое неистовство против элитных противников или в подземельях, Сдерживание, пока цель сосредоточена на вас, уход за питомцем (в Forever здоровье скрыто, поэтому Лечение питомца — за вами). Необязательный шаг с Обжигающей ловушкой по умолчанию выключен."
L["rm.forever.hunter.survival.weave.Name"] = "Выживание, чередование с двуручным оружием (Wowhead)"
L["rm.forever.hunter.survival.weave.Description"] = "Чередование «вошёл-вышел» по Wowhead для охотника «Выживания» с двуручным оружием — альтернатива рекомендуемой встроенной ротации «Выживание» в ближнем бою, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. В ближнем бою: Укус мангуста и Удар ящера; когда до готовности Удара ящера больше 2,5 секунды — Удар долгонога и отход. Вне ближнего боя: Укус змеи, Чародейский выстрел, Прицельный выстрел и Автоматическая стрельба, пока Удар ящера почти не будет готов, затем снова в ближний бой. Передвигаетесь вы сами; RM учитывает вашу дистанцию."
L["rm.mop.hunter.beastmastery.Name"] = "Рекомендуемая"
L["rm.mop.hunter.beastmastery.Description"] = "Выбирается автоматически при специализации «Повелитель зверей». Начинает бой Меткой охотника и Командой «Взять!», затем: Убийственный выстрел, Команда «Взять!» (ненадолго придерживается, когда Звериный гнев вот-вот будет готов), Стая воронов, Ярость рыси, Ужасный зверь и ваш выстрел из таланта 6-го ряда, если он взят, Сконцентрированный огонь при пяти наложениях Бешенства (или при четырёх, которые вот-вот спадут), но не во время Звериного гнева, Укус змеи на целях, которые проживут достаточно долго, Выстрел кобры для его обновления, Чародейский выстрел при 80 ед. концентрации или во время Звериного гнева, затем Выстрел кобры (до 81 уровня — Верный выстрел). Когда с вами сражаются два и более врага, поддерживает Удар зверя Залпом, приберегает Команду «Взять!» на лишнюю концентрацию против больших групп и предлагает Взрывную ловушку от трёх врагов. Напоминания: питомец призван, воскрешён и вылечен, Дух ястреба или Дух железного ястреба, Встречный выстрел, Рвение, а также Звериный гнев, Быстрая стрельба, Звериный натиск и расовые способности, когда бой того стоит (элитный противник, подземелье или рейд или цель, которая проживёт достаточно долго). Расстановка ловушек, Перенаправление, Притвориться мертвым и защитные способности остаются за вами; напоминания о Живости и Сдерживании по умолчанию выключены."
L["rm.mop.hunter.marksmanship.Name"] = "Рекомендуемая"
L["rm.mop.hunter.marksmanship.Description"] = "Выбирается автоматически при специализации «Стрельба». Заранее применяет Прицельный выстрел, затем: Верный выстрел парами для поддержания Устойчивой концентрации (с 63 уровня), Выстрел химеры, Укус змеи на целях, которые проживут достаточно долго, Прицельный выстрел всякий раз, когда «Огонь!» делает его мгновенным, Убийственный выстрел, ваши таланты и Прицельный выстрел с полным временем применения, пока у цели больше 80% здоровья, под Быстрой стрельбой или Жаждой крови, при 85 ед. концентрации или когда до Выстрела химеры остаётся несколько секунд. Чародейский выстрел — только в движении; иначе Верный выстрел. Четыре и более врага: Выстрел химеры, мгновенный Прицельный выстрел, Залп, Убийственный выстрел, Взрывная ловушка. Те же напоминания, что и в других встроенных ротациях охотника. Если вы предпочитаете тратить лишнюю концентрацию на Чародейский выстрел, используйте вариант с Чародейским выстрелом."
L["rm.mop.hunter.marksmanship.icyveins.Name"] = "Трата на Чародейский выстрел (Icy Veins)"
L["rm.mop.hunter.marksmanship.icyveins.Description"] = "Альтернатива встроенной ротации «Стрельба» — так её играют Icy Veins, Method, wowtbc.gg и Hekili: Прицельный выстрел с полным временем применения — только при здоровье цели выше 80% или под Быстрой стрельбой или Жаждой крови, а лишняя концентрация вместо этого уходит на Чародейский выстрел при 60. Устойчивая концентрация обновляется, когда остаётся меньше 4 секунд; против четырёх и более врагов первым идёт Залп. По умолчанию выключена: включите её и выключите встроенную ротацию «Стрельба» или повысьте её приоритет."
L["rm.mop.hunter.survival.Name"] = "Рекомендуемая"
L["rm.mop.hunter.survival.Description"] = "Выбирается автоматически при специализации «Выживание». Начинает бой Меткой охотника, Черной стрелой и Разрывным выстрелом, затем: Разрывной выстрел по готовности и при каждом «На изготовку!», Убийственный выстрел, Черная стрела на целях, которые проживут достаточно долго, ваши таланты, Укус змеи, поддерживаемый Выстрелом кобры, Чародейский выстрел при 75 ед. концентрации, при Охотничьем азарте или при 55, если Черная стрела не скоро будет готова, затем Выстрел кобры (до 81 уровня — Верный выстрел). Два и более врага: сначала Залп при «На изготовку!» с полной концентрацией, Разрывной выстрел — до пяти целей, Убийственный выстрел, Черная стрела, Взрывная ловушка от трёх врагов, Залп для траты. Те же напоминания, что и в других встроенных ротациях охотника; ловушки ради срабатываний «На изготовку!» остаются за вами."
L["rm.mop.hunter.unspecialized.Name"] = "До выбора специализации"
L["rm.mop.hunter.unspecialized.Description"] = "Для уровней 1–9 и любого охотника, который не выбрал специализацию; встроенные ротации «Повелитель зверей», «Стрельба» и «Выживание» вступают в силу, как только вы выберете специализацию. Начинает бой Меткой охотника и Чародейским выстрелом, затем Укус змеи на целях, которые проживут достаточно долго, Залп против трёх и более врагов, Чародейский выстрел, Верный выстрел и Автоматическая стрельба. Напоминает призвать, воскресить и вылечить питомца и поддерживать Дух ястреба."
L["rm.retail.hunter.beastmastery.Name"] = "Боевой помощник Blizzard"
L["rm.retail.hunter.beastmastery.Description"] = "Рекомендуется для специализации «Повелитель зверей». Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight (питомца он призывает сам); пока вы применяете или поддерживаете заклинание, ротация ждёт. Рядом с ним — напоминания о том, что Боевой помощник оставляет вам: Кровопролитие и ваша расовая способность в бою, Встречный выстрел против прерываемого заклинания, а также Выживает сильнейший по готовности в бою. В бою заклинания противников скрыты, поэтому прерывание загорается только там, где игра его показывает; на Retail здоровье скрыто, поэтому момент для защитных способностей (включая Живость и Дух черепахи) — на ваше усмотрение. За вами остаются: аксессуары, Перенаправление и уход за питомцем."
L["rm.retail.hunter.beastmastery.guide.Name"] = "Для справки (SimulationCraft и Icy Veins)"
L["rm.retail.hunter.beastmastery.guide.Description"] = "Только для справки, по умолчанию выключена: оптимизированный приоритет «Повелителя зверей». Заряды, восстановление способностей и срабатывания скрыты от аддонов в бою в Midnight, поэтому этот список не может там работать; читайте его или продублируйте, чтобы поэкспериментировать. Концентрация скрыта в Retail. Перед боем призывает питомца и ставит Метку охотника на цель. Разрывающий выстрел прямо перед Звериным гневом или до переполнения зарядов; Звериный гнев; Команда \"Взять!\" при Вое вожака стаи или Друге природы, либо свободно, пока до Звериного гнева далеко; Выстрел кобры при Клыке кобры; Выстрел кобры; Разрывающий выстрел, когда на Выстрел кобры не хватает концентрации. Темный следопыт: Черная стрела во время Губительного обстрела и Стенающая стрела, когда он заканчивается. Против трёх и более врагов (двух с Ударом зверя): Дикая взбучка, чтобы запустить Удар зверя, затем, пока он действует, Команда \"Взять!\", Разрывающий выстрел и Выстрел кобры. Напоминания: Кровопролитие и вспомогательные напоминания встроенной ротации с Боевым помощником."
L["rm.retail.hunter.initial.Name"] = "Боевой помощник Blizzard"
L["rm.retail.hunter.initial.Description"] = "Рекомендуется до выбора специализации (пока игра сообщает начальную специализацию охотника). Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight; пока вы применяете или поддерживаете заклинание, ротация ждёт. Рядом с ним — общие напоминания всех встроенных ротаций охотника, каждое — как только вы знаете соответствующее заклинание. Когда на 10 уровне вы выбираете специализацию, её встроенные ротации вступают в силу."
L["rm.retail.hunter.marksmanship.Name"] = "Боевой помощник Blizzard"
L["rm.retail.hunter.marksmanship.Description"] = "Рекомендуется для специализации «Стрельба». Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight; пока вы применяете или поддерживаете заклинание, ротация ждёт. Рядом с ним — напоминания о том, что Боевой помощник оставляет вам: Меткий выстрел и ваша расовая способность в бою, Встречный выстрел против прерываемого заклинания, а также Выживает сильнейший по готовности в бою. В бою заклинания противников скрыты, поэтому прерывание загорается только там, где игра его показывает; на Retail здоровье скрыто, поэтому момент для защитных способностей (включая Живость и Дух черепахи) — на ваше усмотрение."
L["rm.retail.hunter.marksmanship.guide.Name"] = "Для справки (SimulationCraft и Icy Veins)"
L["rm.retail.hunter.marksmanship.guide.Description"] = "Только для справки, по умолчанию выключена: оптимизированный приоритет «Стрельбы», который тратит Точные выстрелы до следующего Прицельного выстрела. Срабатывания и заряды скрыты в бою в Midnight, поэтому ротация не может там работать; концентрация скрыта в Retail, поэтому Залп при 70 концентрации против групп не используется. Ставит Метку охотника на цель и начинает бой с Прицельного выстрела. Часовой: Разрывной выстрел, Беглый огонь, Меткий выстрел, Лунный шакрам до конца его окна, Прицельный выстрел под Метким выстрелом без Точных выстрелов, Быстрая стрельба, Убийственный выстрел, Залп (против двух врагов с Духом гидры) или Чародейский выстрел при Точных выстрелах, Прицельный выстрел, Лунный шакрам, Верный выстрел. Темный следопыт: сначала Черная стрела при Точных выстрелах, без Разрывного выстрела во время «На изготовку!», Прицельный выстрел до переполнения зарядов, Стенающая стрела. Против трёх и более врагов с Коварными выстрелами: Разрывной выстрел, Беглый огонь, Залп, чтобы наложить Коварные выстрелы, Меткий выстрел, затем, пока действуют Коварные выстрелы, Быстрая стрельба и Прицельный выстрел. Применять Меткий выстрел ради 30 наложений «В яблочко» или по цели без метки — решать вам."
L["rm.retail.hunter.survival.Name"] = "Боевой помощник Blizzard"
L["rm.retail.hunter.survival.Description"] = "Рекомендуется для специализации «Выживание». Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight (питомца он призывает сам); пока вы применяете или поддерживаете заклинание, ротация ждёт. Рядом с ним — напоминания о том, что Боевой помощник оставляет вам: Захват врасплох и ваша расовая способность в бою, Намордник против прерываемого заклинания, а также Выживает сильнейший по готовности в бою. В бою заклинания противников скрыты, поэтому прерывание загорается только там, где игра его показывает; на Retail здоровье скрыто, поэтому момент для защитных способностей (включая Живость и Дух черепахи) — на ваше усмотрение."
L["rm.retail.hunter.survival.guide.Name"] = "Для справки (SimulationCraft)"
L["rm.retail.hunter.survival.guide.Description"] = "Только для справки, по умолчанию выключена: приоритет «Выживания» по SimulationCraft, где Команда «Взять!» накапливает Наконечник копья, а Захват врасплох, Огнестрел, Огнебомба и Удар ящера его тратят. Наконечник копья и заряды скрыты в бою в Midnight, поэтому ротация не может там работать. Призывает питомца, ставит Метку охотника на цель и начинает бой с Огнебомбы. Часовой: Команда «Взять!» без Наконечника копья, Огнестрел, Огнебомба при Метке часового, Команда «Взять!» перед готовым Захватом врасплох, Захват врасплох, Лунный шакрам, Удар ящера, затем Команда «Взять!», Огнебомба и Захват врасплох. Вожак стаи: Команда «Взять!» при Вое вожака стаи, затем Захват врасплох, Огнебомба, Огнестрел и Удар ящера с Наконечником копья. Против трёх и более врагов: Огнестрел и Огнебомба перед Захватом врасплох, Взмах ящера. Напоминания: Дух орла вне ближнего боя и вспомогательные напоминания."
L["rm.sod.hunter.melee.Name"] = "Ближний бой (SoD)"
L["rm.sod.hunter.melee.Description"] = "Выбирается в игровом мире сезона открытий, когда вы выгравировали Обходной удар, Удар виверны или Разделку туши и ни Выстрел химеры, ни Разрывной выстрел. Поддерживает положительный эффект Обходного удара, Укус мангуста при четырёх наложениях Неистовства ящера, Удар виверны при Хитрых ударах, Удар ящера при каждом сбросе восстановления, затем Укус мангуста, Удар виверны, Обходной удар и Разделка туши; Обжигающая ловушка и Подрезать крылья — только в свободные моменты. Разделка туши и Взрывная ловушка против трёх и более врагов; Укус змеи и выстрелы, пока вы не достаёте до цели. Напоминания: Дух сокола (до 60 уровня — Дух ястреба), Дух гадюки при мане ниже 5%, уход за питомцем (не нужен с выгравированным Одиноким волком), Быстрая стрельба и расовые способности, когда Обходной удар набрал наложения, Звериный гнев. Позиционирование и команды питомцу остаются за вами."
L["rm.sod.hunter.ranged.Name"] = "Дальний бой (SoD)"
L["rm.sod.hunter.ranged.Description"] = "Любой охотник дальнего боя в игровом мире сезона открытий, с 1 по 60 уровень; руны используются, как только выгравированы. Укус змеи висит всегда и обновляется Выстрелом химеры. С руной Убийственного выстрела на ногах: Залп при четырёх Коварных выстрелах, Убийственный выстрел во время Быстрой стрельбы и по целям в фазе добивания, Выстрел химеры, затем Взрывная ловушка и Чародейский выстрел, пока Залп восстанавливается. Без неё: Выстрел химеры, Прицельный выстрел при двух наложениях Навыков снайпера (без этой руны — сразу после автоматического выстрела), ловушки незадолго до готовности Выстрела химеры (Ледяная ловушка — только чтобы срабатывало «На изготовку!»), Разрывной выстрел, Верный выстрел, Залп, Чародейский выстрел. Удары ближнего боя, когда враг слишком близко, мгновенные выстрелы в движении, ловушки, Залп и Град стрел против трёх и более врагов. Напоминания: Дух ястреба, Дух гадюки при мане ниже 10%, Львиное сердце, Аура меткого выстрела, уход за питомцем (не нужен с выгравированным Одиноким волком), Сконцентрированный огонь при пяти наложениях Бешенства, Быстрая стрельба, расовые способности и Звериный гнев против элитных противников и в подземельях. С выгравированным «На изготовку!» — Ледяная ловушка перед боем. Вплетение ударов ближнего боя и позиционирование остаются за вами."
L["rm.tbc.hunter.ranged.simulator.Name"] = "Урон в дальнем бою (симулятор)"
L["rm.tbc.hunter.ranged.simulator.Description"] = "Уровни 1–70, любая ветка талантов. Начинает бой с Метки охотника, Прицельного выстрела и Автоматической стрельбы, не прерывает Автоматическую стрельбу и использует удары ближнего боя, когда цель добирается до вас. До изучения Верного выстрела поддерживает Укус змеи и тратит ману на Прицельный, Чародейский выстрел и Залп только при большом запасе маны. С 62 уровня: Залп по готовности, Верный выстрел сразу после каждого автоматического выстрела, Чародейский выстрел, чтобы заполнить паузу, Укус змеи в одиночной игре. Если с вами сражаются три и более врага — Залп всякий раз, когда он готов. Напоминает о аспектах (Дух гадюки при нехватке маны, снова Дух ястреба на половине маны), уходе за питомцем, Команде «Взять!», крупных способностях с восстановлением против элитных противников и боссов и о Глушащем выстреле. Команды питомцу, Перенаправление, ловушки, Град стрел, вплетение ударов ближнего боя и Притвориться мертвым остаются за вами."
L["rm.tbc.hunter.ranged.wowhead.Name"] = "Урон в дальнем бою (Wowhead)"
L["rm.tbc.hunter.ranged.wowhead.Description"] = "Уровни 1–70, любая ветка талантов, по рейдовым советам Wowhead. Те же начало боя, ближний бой, выстрелы для прокачки, Залп против нескольких целей и напоминания, что и в версии симулятор, но после изучения Верного выстрела после каждого автоматического выстрела предлагает только Залп и Верный выстрел: без Чародейского выстрела как заполнителя (кроме как в движении), без Укуса змеи и без напоминания о Духе гадюки. Команды питомцу, Перенаправление, ловушки, Град стрел, вплетение ударов ближнего боя и Притвориться мертвым остаются за вами. Альтернатива рекомендуемой встроенной ротации «Дальний бой» (симулятор), отключена по умолчанию: включите её и выключите ту или повысьте её приоритет."
